                             UVM_LITTLE_ENDIAN, 1);

        CTRL = axi_reg_ctrl::type_id::create("CTRL");
        CTRL.configure(this, null, "");
        CTRL.build();
        axi_map.add_reg(CTRL, 32'h00000000, "RW");

        STATUS = axi_reg_status::type_id::create("STATUS");
        STATUS.configure(this, null, "");
        STATUS.build();
        axi_map.add_reg(STATUS, 32'h00000004, "RO");

        CONFIG = axi_reg_config::type_id::create("CONFIG");
        CONFIG.configure(this, null, "");
        CONFIG.build();
        axi_map.add_reg(CONFIG, 32'h00000008, "RW");

        INT_ENABLE = axi_reg_int_enable::type_id::create("INT_ENABLE");
        INT_ENABLE.configure(this, null, "");
        INT_ENABLE.build();
        axi_map.add_reg(INT_ENABLE, 32'h0000000C, "RW");

        INT_STATUS = axi_reg_int_status::type_id::create("INT_STATUS");
        INT_STATUS.configure(this, null, "");
        INT_STATUS.build();
        axi_map.add_reg(INT_STATUS, 32'h00000010, "RW");

        SCRATCH = axi_reg_scratch::type_id::create("SCRATCH");
        SCRATCH.configure(this, null, "");
        SCRATCH.build();
        axi_map.add_reg(SCRATCH, 32'h00000014, "RW");

