        axi_map.add_reg(COUNTER, 32'h00000018, "RO");

        ID = axi_reg_id::type_id::create("ID");
        ID.configure(this, null, "");
        ID.build();
        axi_map.add_reg(ID, 32'h0000001C, "RO");

